import{_ as i,o as u,c as n,a2 as k}from"./chunks/framework.CqpfiAoK.js";const z=JSON.parse('{"title":"Nakala 101｜Uboreshaji wa Nguvu · Nguvu ya Hisi Asili · Njia ya Mafunzo ya Rén Zú Mwanamke","description":"","frontmatter":{"title":"Nakala 101｜Uboreshaji wa Nguvu · Nguvu ya Hisi Asili · Njia ya Mafunzo ya Rén Zú Mwanamke","no":101,"module":1,"tags":["境界","感元境","人族","女性","修炼路径"],"related":["14-修炼境界统一划分","51-人族定位与特质","41-共生劳动法","19-修炼伦理与边界"]},"headers":[],"relativePath":"sw/101_模块1-感元境-女性人族修炼路径.md","filePath":"sw/101_模块1-感元境-女性人族修炼路径.md"}'),o={name:"sw/101_模块1-感元境-女性人族修炼路径.md"};function t(s,a,h,l,m,w){return u(),n("div",null,[...a[0]||(a[0]=[k('<h1 id="nakala-101-nguvu-ya-hisi-asili-njia-ya-mafunzo-tofauti-za-vipaji-na-sifa-za-nafsi-za-ren-zu-mwanamke" tabindex="-1">Nakala 101｜Nguvu ya Hisi Asili: Njia ya Mafunzo, Tofauti za Vipaji, na Sifa za Nafsi za Rén Zú Mwanamke <a class="header-anchor" href="#nakala-101-nguvu-ya-hisi-asili-njia-ya-mafunzo-tofauti-za-vipaji-na-sifa-za-nafsi-za-ren-zu-mwanamke" aria-label="Permalink to &quot;Nakala 101｜Nguvu ya Hisi Asili: Njia ya Mafunzo, Tofauti za Vipaji, na Sifa za Nafsi za Rén Zú Mwanamke&quot;">​</a></h1><ul><li>Moduli: Moduli ya Kwanza · Uboreshaji wa Kina wa Nguvu | Msingi wa Rejeo: Hati 14, 51, 41, 19</li></ul><h2 id="utangulizi-kipaji-kisichobainishwa-njia-isiyopotezwa" tabindex="-1">Utangulizi: Kipaji kisichobainishwa, Njia isiyopotezwa <a class="header-anchor" href="#utangulizi-kipaji-kisichobainishwa-njia-isiyopotezwa" aria-label="Permalink to &quot;Utangulizi: Kipaji kisichobainishwa, Njia isiyopotezwa&quot;">​</a></h2><p>Kanuni ya Jamhuri ya Kabila Kumi na Elfu ya Heng Yuan Zhou (Cosmos Asili ya Roho Kumi na Elfu na Nanga Iliyosawazishwa) inasema kwa uwazi kabisa: viumbe vyote vina sifa sawa za mageuzi. &quot;Usawa&quot; hapa si kukata kila mtu kwenye ukungu mmoja, bali ni kila aina ya kipaji kupata njia yake. Nguvu ya Hisi Asili kama mwanzo wa nguvu tisa ni chumba cha kwanza cha majaribio ya kanuni hii — kipaji, nafsi, na njia ya Rén Zú mwanamke hapa kwa muda mrefu imepotoshwa, kuzimwa, au kunyonywa na mfumo wa Kundi la Wawindaji, ilhali katika Ustaarabu wa Usawa wa Nanga, kwa mara ya kwanza zinatibiwa kama rasilimali za mageuzi za kweli.</p><p>Makala hii, kulingana na Mgawanyiko Uliounganishwa wa Nguvu za Mafunzo (Hati 14) na Nafasi na Tabia za Rén Zú (Hati 51), inaeleza njia ya mafunzo, tofauti za vipaji, na sifa za nafsi za Rén Zú mwanamke katika Nguvu ya Hisi Asili.</p><p>Kanuni Muhimu Sita za Juu ni msingi wa hoja ya makala hii: Kanuni ya Kupinga Unyanyasaji — nishati ya mwanafunzi mwanamke hutoka kwa mzunguko, si kwa kunyonywa; Kanuni ya Jamhuri ya Kabila Kumi na Elfu — jinsia si kizingiti cha mageuzi, kila kipaji kinastahili kuthaminiwa; Kanuni ya Kupanda Mwelekeo kwa Pamoja — ukuaji wao hatimaye hurudishwa kwa Kabila Kumi na Elfu; Kanuni ya Nidhamu ya Sababu-Natija — mafunzo hayachanganyi sababu ya wengine na mazingira; Kanuni ya Kipaumbele cha Sheria — mfumo wa sheria wa njia ya Rén Zú mwanamke ni thabiti na wenyewe, bila kubadilishwa kwa urahisi wa hadithi, unaweza kupanuka bila kikomo bila kuporomoka. Kanuni ya Usawa wa Ukombozi wa Kila Kiumbe inasisitiza kila mtu ana Nguvu Isiyo na Mwisho ya Msingi; wanafunzi wanawake wavivu wanabaki na nguvu ya msingi ya uhakika na hawataondolewa na wakati, wakati wanawake wenye tamaa na Vijana Wakuu wa Kike wanaweza kuongeza ngazi za juu za nguvu ya bila kikomo; asili ya nguvu ya bila kikomo ni ya kila mtu, na unyanyasaji kawaida hupoteza maana.</p><h2 id="i-picha-na-tofauti-za-vipaji-za-ren-zu-mwanamke-katika-nguvu-ya-hisi-asili" tabindex="-1">I. Picha na Tofauti za Vipaji za Rén Zú Mwanamke katika Nguvu ya Hisi Asili <a class="header-anchor" href="#i-picha-na-tofauti-za-vipaji-za-ren-zu-mwanamke-katika-nguvu-ya-hisi-asili" aria-label="Permalink to &quot;I. Picha na Tofauti za Vipaji za Rén Zú Mwanamke katika Nguvu ya Hisi Asili&quot;">​</a></h2><p>Kulingana na Hati 51, kati ya tabia za kiakili za Rén Zú, &quot;utajiri wa hisia&quot; na &quot;uwezo wa ushirikiano wa kijamii&quot; ni faida za wazi; katika Nguvu ya Hisi Asili, nguvu inayolenga &quot;hisi&quot;, Rén Zú mwanamke kwa ujumla huonyesha picha ifuatayo:</p><ul><li>Hisi nyeti: hisia ya mabadiliko madogo ya nishati kwa ujumla ni ya kina zaidi, faida ya asili katika hatua ya kutambua nishati ni dhahiri</li><li>Huruma kali: nyeti kwa hali ya nishati ya wengine na mazingira, huwa &quot;msawazishaji&quot; katika mafunzo ya ushirikiano</li><li>Msukumo wa kihisia: hisia kali (ulinzi, uhusiano, imani) zinaweza kuamsha uwezo mkubwa, lakini pia zinaweza kuongeza mabadiliko ya hisia yanayoingilia mafunzo</li><li>Ustahimilivu wa ndani: ustahimilivu wa kiakili mbele ya vikwazo si chini ya kundi lolote, na huwa na mwelekeo wa kutafuta msaada badala ya kulazimisha</li></ul><p>Tofauti za vipaji lazima zielezwe kwa uaminifu, lakini hazitumiwe kuunda ngazi mpya: hisi ya kina haimaanishi &quot;udhaifu&quot;, kama faida ya kimwili haimaanishi &quot;nguvu&quot;. Uzito wa ustaarabu haupima kipaji kimoja kamwe, bali kiwango cha mchanganyiko wa kipaji na makubaliano — mwanafunzi mwenye uwezo wa kuhisi na kushughulikia, katika mzunguko wa pande mbili wa asili ya Kabila Kumi na Elfu, mara nyingi hutoa mchango unaozidi matarajio.</p><h2 id="ii-njia-ya-mafunzo-maendeleo-ya-hisi-kulingana-na-asili" tabindex="-1">II. Njia ya Mafunzo: Maendeleo ya Hisi Kulingana na Asili <a class="header-anchor" href="#ii-njia-ya-mafunzo-maendeleo-ya-hisi-kulingana-na-asili" aria-label="Permalink to &quot;II. Njia ya Mafunzo: Maendeleo ya Hisi Kulingana na Asili&quot;">​</a></h2><p>Njia inayopendekezwa kwa Rén Zú mwanamke katika Nguvu ya Hisi Asili inasisitiza &quot;kufuata asili, kujaza upungufu&quot;:</p><ol><li>Kuzaliwa kwa Hisia: kuingia haraka katika hali kupitia hisi ya kina, mafunzo ya &quot;utambuzi&quot; badala ya &quot;ufahamu&quot; — wanawake wengi katika hatua hii hutumia muda kidogo kuliko wastani</li><li>Kumeza Msingi: kuchagua Mfumo wa Mzunguko wa Maisha (seti 2, inayolingana na nguvu &quot;hisi-maisha&quot;) kama mafunzo ya msingi, dhana ya &quot;mzunguko mzuri wa nishati ya maisha&quot; inafanana sana na sifa za wanawake wa hisi ya kina na huruma</li><li>Kutambua Nishati: wakati wa kuunda ramani ya nishati ya kibinafsi, kuzingatia mwingiliano wa &quot;nishati ya hisia&quot; na &quot;nishati ya mazingira&quot;, kuzuia uchafuzi wa nishati kutoka huruma</li><li>Misingi na Mkusanyiko wa Asili: kushinda kwa &quot;utulivu&quot;, kutofuata kasi, kuhakikisha msingi safi wakati mzunguko wa ndani unaanzishwa</li></ol><p>Ni muhimu kusisitiza kwamba njia ni &quot;pendekezo&quot;, si &quot;sheria&quot;: katika Mfumo wa Kurudia kwa Ufafanuzi na Mfumo wa Udhibiti wa Sheria za Nafasi pia kuna wanawake wengi wanaong&#39;aa. Maana ya mfumo wa tathmini ya usawaziko wa mfumo (Hati 10) ni kuwezesha kila mtu kuchagua kulingana na data yake, badala ya mitazamo potofu ya kijinsia.</p><h2 id="iii-sifa-za-nafsi-hisia-ni-nguvu-pia-ni-jaribio" tabindex="-1">III. Sifa za Nafsi: Hisia ni Nguvu, pia ni Jaribio <a class="header-anchor" href="#iii-sifa-za-nafsi-hisia-ni-nguvu-pia-ni-jaribio" aria-label="Permalink to &quot;III. Sifa za Nafsi: Hisia ni Nguvu, pia ni Jaribio&quot;">​</a></h2><p>Sifa za nafsi za Rén Zú mwanamke katika Nguvu ya Hisi Asili zinazingatia &quot;hali ya pande mbili ya hisia&quot;:</p><ul><li>Hisia kama mafuta: kulinda familia na marafiki, kushikamana na nyumbani, kuamini usawa — hisia hizi zinaweza kufungua njia zote za hisi, na wakati wa kuvunja vikwazo huamsha uwezo unaozidi wa kawaida</li><li>Huruma kama hatari: huruma nyingi kwa mateso ya wengine na uchafuzi wa mazingira zinaweza kuleta nishati hasi ndani yako, kusababisha uchafuzi wa hisi na usawa wa nafsi</li><li>Uhitaji wa nanga ya hisia: uhusiano thabiti wa hisia (mwalimu, wenzake, Mtandao wa Nanga) ni mpira wa usalama wa nafsi; kuwa peke yake bila msaada ni hatari kubwa ya nafsi</li></ul><p>Suluhu ya Heng Yuan Zhou si &quot;kukandamiza hisia&quot;, bali &quot;kupanga hisia&quot;: Mtandao wa Ālaya + usimamizi wa tabaka nyingi utatoa onyo la uchafuzi wa hisi, mtandao wa waalimu hutoa msaada wa hisia, na kanuni wa ridhaa iliyoarifiwa katika maadili ya mafunzo (Hati 19) inahakikisha kwamba mafunzo yote ya pamoja au ushiriki wa nishati ni kwa hiari — hii ni kukanusha misingi dhidi ya uovu wa zama za unyanyasaji: &quot;tanuru&quot;, &quot;zana za damu&quot;, &quot;unyonyaji wa mafunzo ya pamoja&quot;.</p><h2 id="iv-ulinzi-maalum-kuandika-usawa-katika-taasisi" tabindex="-1">IV. Ulinzi Maalum: Kuandika Usawa katika Taasisi <a class="header-anchor" href="#iv-ulinzi-maalum-kuandika-usawa-katika-taasisi" aria-label="Permalink to &quot;IV. Ulinzi Maalum: Kuandika Usawa katika Taasisi&quot;">​</a></h2><p>Ulinzi wa wanawake wa mafunzo si kauli mbiu za kimaadili, bali ni vifungu vya kitaasisi:</p><ul><li>Marekebisho ya ujauzito: kulingana na roho ya ulinzi maalum kwa maisha ya wanawake wajawazito kutoka Sheria ya Kazi ya Usawa (Hati 41), mpango wa mafunzo hupunguza kiotomatiki nguvu, na wakati wa likizo ya uzazi rasilimali za mafunzo huendelea kutolewa</li><li>Msamaha wa kunyonyesha: wakati wa kunyonyesha, kuachiliwa kutoka kazi za mafunzo za mzigo mzito; Mtandao wa Nanga huhifadhi maendeleo ya mafunzo na haki za uthibitisho wa nguvu</li><li>Vifungu vya kupinga ubaguzi: ugawaji wa rasilimali, mapendekezo ya waalimu, uthibitisho wa nguvu zote zinatokana na data na mchango, kizingia chochote kilichofichwa kulingana na jinsia</li><li>Wavu wa usalama wa kimaadili: yoyote ya kulazimisha au kushawishi kwa jina la &quot;mafunzo ya pamoja&quot; au &quot;mafunzo ya msaada&quot; inachukuliwa kama kesi kuu ya maadili ya mafunzo</li></ul><p>Vifungu hivi pamoja huunda toleo la kijinsia la &quot;Njia kwa Kila Mtu&quot;: Rén Zú mwanamke si &quot;dhaifu anayehitaji utunzaji&quot;, bali &quot;mjenzi anayestahili kuthaminiwa na taasisi&quot;.</p><h2 id="v-pointi-tano-za-msingi" tabindex="-1">V. Pointi Tano za Msingi <a class="header-anchor" href="#v-pointi-tano-za-msingi" aria-label="Permalink to &quot;V. Pointi Tano za Msingi&quot;">​</a></h2><ul><li>Kupinga uharibifu wa nishati: hisi ya kina na usawazishaji wa huruma ni uwezo adimu unaohitajika sana na ustaarabu wa anga nyingi zaidi; mfumo wa zamani uliwaweka katika &quot;nafasi ya msaidizi&quot;, huku ndiko kulikuwa na upotevu mkubwa</li><li>Kupinga unyanyasaji: kutokomeza kimsingi unyanyasaji wa aina ya &quot;tanuru&quot; na &quot;zana za damu&quot;; ridhaa iliyoarifiwa ni msingi</li><li>Kulinganisha paa la Táng Luó: mfumo wa ustawi wa zama za zamani haukuwahi kuwatazama wanawake wa mafunzo kama masomo ya kujitegemea; ulinzi wa zawadi hauwezi kuchukua nafasi ya ujenzi wa pamoja wa usawa</li><li>Kufunika kwa Kabila Kumi na Elfu: Rén Zú mwanamke anashiriki kiwango kimoja cha nguvu na Rén Zú mwanaume na makabila mengine, zote ziko katika upeo wa 99%</li><li>Ufunguzi wa kina wa anga nyingi zaidi: njia za Nguvu ya Hisi Asili zimefunguliwa bila malipo kwa wanawake, hatua ya kwanza ya mfululizo wa wazi inapatikana kwa wote</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Wanawake wa mafunzo katika Nguvu ya Hisi Asili, kwa hisi ya kina zaidi, wanathibitisha kanuni kuu zaidi: hakuna kipaji cha juu au cha chini, ni kipaji kilichowekwa mahali pazuri. Ustaarabu wa Usawa wa Nanga haufanyi &quot;mtoaji wa sadaka&quot;, bali &quot;mtandao wa njia&quot; — huweka njia chini ya kila aina ya kipaji, ili katika cosmos ya ushirikiano wa Kabila Kumi na Elfu, hakuna anayehitaji kujikana ili kupata sifa ya mageuzi.</p><h2 id="husika" tabindex="-1">Husika <a class="header-anchor" href="#husika" aria-label="Permalink to &quot;Husika&quot;">​</a></h2><ul><li>Hati zinazohusiana: <a href="./14-修炼境界统一划分.html">14-修炼境界统一划分</a> · <a href="./51-人族定位与特质.html">51-人族定位与特质</a> · <a href="./41-共生劳动法.html">41-共生劳动法</a> · <a href="./19-修炼伦理与边界.html">19-修炼伦理与边界</a></li><li>Tovuti rasmi: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',28)])])}const y=i(o,[["render",t]]);export{z as __pageData,y as default};
